function getPackageSelectItemOptions(packages, packageTypeName) {
    return {
        items: packages,
        getId(item) {
            return item.id;
        },
        getDisplayName(item) {
            return item.getName();
        },
        getItemNotFoundMessage(itemId) {
            return `No ${packageTypeName} found with id "${itemId}".`;
        },
